adcs_quat_t q_conj_curr = adcs_quat_conjugate(&q_curr_norm);
adcs_quat_t q_err = adcs_quat_multiply(&q_target_norm, &q_conj_curr);

if (q_err.w < 0.0) {
    q_err.w = -q_err.w;
    q_err.x = -q_err.x;
    q_err.y = -q_err.y;
    q_err.z = -q_err.z;
}

double half_angle = acos(fmin(1.0, fmax(-1.0, q_err.w)));
double sin_half_angle = sin(half_angle);
adcs_vec3_t e = {0.0, 0.0, 0.0};
double error_angle = 2.0 * half_angle;

if (sin_half_angle > 1e-12) {
    double scale = (2.0 * half_angle) / sin_half_angle;
    e.x = scale * q_err.x;
    e.y = scale * q_err.y;
    e.z = scale * q_err.z;
}

double rate_mag = adcs_vec3_norm(ra_input.body_rate_rad_s);

ra_mode_t new_mode = ra_state.mode;
int reset_integral = 0;

switch (ra_state.mode) {
    case RA_RATE_DAMP:
        if (rate_mag >= ra_config.rate_exit_rad_s) {
            ra_state.transition_samples = 0;
        } else {
            if (ra_state.transition_samples + 1 >= ra_config.rate_samples) {
                new_mode = RA_COARSE;
                ra_state.transition_samples = 0;
            } else {
                ra_state.transition_samples++;
            }
        }
        break;
    case RA_COARSE:
        if (error_angle <= ra_config.fine_enter_rad && rate_mag <= ra_config.rate_enter_rad_s) {
            if (ra_state.transition_samples + 1 >= ra_config.fine_samples) {
                new_mode = RA_FINE;
                ra_state.transition_samples = 0;
            } else {
                ra_state.transition_samples++;
            }
        } else {
            ra_state.transition_samples = 0;
        }
        break;
    case RA_FINE:
        if (error_angle >= ra_config.fine_exit_rad || rate_mag >= ra_config.rate_exit_rad_s) {
            new_mode = RA_COARSE;
            reset_integral = 1;
            ra_state.transition_samples = 0;
        } else {
            if (error_angle <= ra_config.hold_enter_rad && rate_mag <= ra_config.hold_rate_rad_s) {
                if (ra_state.transition_samples + 1 >= ra_config.hold_samples) {
                    new_mode = RA_HOLD;
                    ra_state.transition_samples = 0;
                } else {
                    ra_state.transition_samples++;
                }
            } else {
                ra_state.transition_samples = 0;
            }
        }
        break;
    case RA_HOLD:
        if (error_angle >= ra_config.hold_exit_rad || rate_mag >= ra_config.hold_rate_exit_rad_s) {
            new_mode = RA_FINE;
            ra_state.transition_samples = 0;
        }
        break;
    default:
        break;
}

int config_valid = 1;
if (!(ra_config.hold_enter_rad < ra_config.hold_exit_rad && 
      ra_config.hold_exit_rad <= ra_config.fine_enter_rad && 
      ra_config.fine_enter_rad < ra_config.fine_exit_rad && 
      ra_config.fine_exit_rad <= ADCS_PI)) {
    config_valid = 0;
}
if (!(ra_config.hold_rate_rad_s < ra_config.hold_rate_exit_rad_s && 
      ra_config.hold_rate_exit_rad_s <= ra_config.rate_enter_rad_s && 
      ra_config.rate_enter_rad_s < ra_config.rate_exit_rad_s)) {
    config_valid = 0;
}
if (ra_config.max_bad_samples < 1 || ra_config.max_bad_samples > 20) {
    config_valid = 0;
}
if (ra_config.kp < 0 || ra_config.kd < 0 || ra_config.ki < 0) {
    config_valid = 0;
}
if (!isfinite(ra_config.dt_s) || ra_config.dt_s <= 0) {
    config_valid = 0;
}
if (!isfinite(ra_config.integral_limit_rad_s) || ra_config.integral_limit_rad_s <= 0) {
    config_valid = 0;
}
if (!isfinite(ra_config.torque_limit_nm) || ra_config.torque_limit_nm <= 0) {
    config_valid = 0;
}
if (ra_config.rate_samples < 1 || ra_config.rate_samples > 20) {
    config_valid = 0;
}
if (ra_config.fine_samples < 1 || ra_config.fine_samples > 20) {
    config_valid = 0;
}
if (ra_config.hold_samples < 1 || ra_config.hold_samples > 20) {
    config_valid = 0;
}

if (!config_valid) {
    ra_state.transition_samples = 0;
