    ra_output.torque_nm.y = 0.0;
    ra_output.torque_nm.z = 0.0;
    ra_output.bad_samples = ra_state.bad_samples;
    ra_output.saturation_mask = 0U;
    return;
}

ra_state.bad_samples = 0;
ra_state.mode = new_mode;

if (reset_integral) {
    ra_state.integral_error_rad_s.x = 0.0;
    ra_state.integral_error_rad_s.y = 0.0;
    ra_state.integral_error_rad_s.z = 0.0;
}

double kp = ra_config.kp;
double ki = ra_config.ki;
double kd = ra_config.kd;

if (new_mode == RA_RATE_DAMP) {
    kp = 0.0;
    ki = 0.0;
} else if (new_mode == RA_COARSE) {
    ki = 0.0;
}

adcs_vec3_t I = ra_state.integral_error_rad_s;
if (new_mode == RA_FINE || new_mode == RA_HOLD) {
    adcs_vec3_t dI = adcs_vec3_scale(&e, ra_config.dt_s);
    I = adcs_vec3_add(&I, &dI);

    I.x = ADCS_CLAMP(I.x, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s);
    I.y = ADCS_CLAMP(I.y, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s);
    I.z = ADCS_CLAMP(I.z, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s);

    // Anti-windup logic for integral
    adcs_vec3_t I_aw = {0,0,0};
    for (int i = 0; i < 3; i++) {
        double ei = (i==0)?e.x:(i==1?e.y:e.z);
        double wi = (i==0)?ra_input.body_rate_rad_s->x:(i==1?ra_input.body_rate_rad_s->y:ra_input.body_rate_rad_s->z);
        double ii_old = (i==0)?I.x:(i==1?I.y:I.z);

        // Note: I here is already clamped. We need to check against the clamped value's effect.
        // Actually, the anti-windup should check if the PROPOSED update (before clamp or after?)
        // "freeze an integral-axis update when that update would drive an already-saturated torque farther into saturation"
        // This implies we look at the torque contribution.

        // Let's re-calculate based on raw update before clamp for fairness, or clamp then check?
        // Standard PI anti-windup: if saturated, don't integrate more in that direction.

        double ii_raw = (i==0)?(ra_state.integral_error_rad_s.x + e.x * ra_config.dt_s):
                         ((i==1)?(ra_state.integral_error_rad_s.y + e.y * ra_config.dt_s):
                                 (ra_state.integral_error_rad_s.z + e.z * ra_config.dt_s));

        // But ra_state.integral_error_rad_s was already updated above!
        // So we lost the old value.
        // Fix: Save old I before update.
    }
    // To fix the loss of old I, we should have saved it.
    // Let's restart integral logic properly.
}

// Corrected Integral Logic
if (new_mode == RA_FINE || new_mode == RA_HOLD) {
    adcs_vec3_t I_old = ra_state.integral_error_rad_s;
    adcs_vec3_t I_new = {0,0,0};

    for (int i = 0; i < 3; i++) {
        double ei = (i==0)?e.x:(i==1?e.y:e.z);
        double ii_raw = (i==0)?(I_old.x + ei * ra_config.dt_s):
                          ((i==1)?(I_old.y + ei * ra_config.dt_s):
                                  (I_old.z + ei * ra_config.dt_s));

        double ii_clamped = ADCS_CLAMP(ii_raw, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s);

        // Check torque saturation effect
        double T_pid_no_int = -kp * ei - kd * ((i==0)?ra_input.body_rate_rad_s->x:((i==1)?ra_input.body_rate_rad_s->y:ra_input.body_rate_rad_s->z));
        double T_old = T_pid_no_int - ki * I_old.m[i];
        double T_new = T_pid_no_int - ki * ii_clamped;

        int old_sat = (fabs(T_old) > ra_config.torque_limit_nm);
        int new_sat = (fabs(T_new) > ra_config.torque_limit_nm);

        if (new_sat && old_sat && fabs(T_new) > fabs(T_old)) {
            I_new.m[i] = I_old.m[i]; // Freeze
        } else {
            I_new.m[i] = ii_clamped;
        }
    }
    ra_state.integral_error_rad_s = I_new;
    I = I_new;
}

adcs_vec3_t T_unclamped;
T_unclamped.x = -kp * e.x - kd * ra_input.body_rate_rad_s->x - ki * I.x;
T_unclamped.y = -kp * e.y - kd * ra_input.body_rate_rad_s->y - ki * I.y;
T_unclamped.z = -kp * e.z - kd * ra_input.body_rate_rad_s->z - ki * I.z;

adcs_actuator_limit_t limit = {
    .min_value = -ra_config.torque_limit_nm,
    .max_value = ra_config.torque_limit_nm,
    .max_slew_per_s = 0.0
};

unint32 sat_mask = 0;
adcs_vec3_t T_limited;

double t_lim_x, t_lim_y, t_lim_z;
adcs_limit_scalar(T_unclamped.x, &limit, &t_lim_x);
adcs_limit_scalar(T_unclamped.y, &limit, &t_lim_y);
adcs_limit_scalar(T_unclamped.z, &limit, &t_lim_z);

T_limited.x = t_lim_x;
T_limited.y = t_lim_y;
T_limited.z = t_lim_z;

if (fabs(T_unclamped.x) > fabs(t_lim_x)) sat_mask |= 1;
if (fabs(T_unclamped.y) > fabs(t_lim_y)) sat_mask |= 2;
if (fabs(T_unclamped.z) > fabs(t_lim_z)) sat_mask |= 4;

ra_output.mode = ra_state.mode;
ra_output.error_angle_rad = error_angle;
ra_output.rate_magnitude_rad_s = rate_mag;
ra_output.torque_nm = T_limited;
ra_output.bad_samples = ra_state.bad_samples;
ra_output.saturation_mask = sat_mask;

