        } else {
            // Sample at or above rate_exit_rad_s clears that evidence.
            // Wait, requirement says: "a sample at or above rate_exit_rad_s clears that evidence."
            // But entering RATE_DAMP is from OFF. The condition to leave RATE_DAMP is rate_samples consecutive <= rate_enter.
            // What clears the evidence inside RATE_DAMP?
            // "rate_samples consecutive samples at or below rate_enter_rad_s enter COARSE; a sample at or above rate_exit_rad_s clears that evidence."
            if (rate_mag >= ra_config.rate_exit_rad_s) {
                ra_state.transition_samples = 0;
            }
        }
        break;

    case RA_COARSE:
        // PD control
        torque_unlimited.x = -ra_config.kp * e.x - ra_config.kd * ra_input.body_rate_rad_s->x;
        torque_unlimited.y = -ra_config.kp * e.y - ra_config.kd * ra_input.body_rate_rad_s->y;
        torque_unlimited.z = -ra_config.kp * e.z - ra_config.kd * ra_input.body_rate_rad_s->z;

        if (angle <= ra_config.fine_enter_rad && rate_mag <= ra_config.rate_enter_rad_s) {
            ra_state.transition_samples++;
            if (ra_state.transition_samples >= ra_config.fine_samples) {
                ra_state.mode = RA_FINE;
                ra_state.transition_samples = 0;
            }
        } else {
            ra_state.transition_samples = 0;
        }
        break;

    case RA_FINE:
        // PID control
        // Update Integral
        adcs_vec3_t scale_e = adcs_vec3_scale(&e, ra_config.dt_s);
        adcs_vec3_t proposed_I = adcs_vec3_add(&ra_state.integral_error_rad_s, &scale_e);

        // Clamp Integral
        adcs_vec3_t limited_I = {
            ADCS_CLAMP(proposed_I.x, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s),
            ADCS_CLAMP(proposed_I.y, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s),
            ADCS_CLAMP(proposed_I.z, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s)
        };

        torque_unlimited.x = -ra_config.kp * e.x - ra_config.kd * ra_input.body_rate_rad_s->x - ra_config.ki * limited_I.x;
        torque_unlimited.y = -ra_config.kp * e.y - ra_config.kd * ra_input.body_rate_rad_s->y - ra_config.ki * limited_I.y;
        torque_unlimited.z = -ra_config.kp * e.z - ra_config.kd * ra_input.body_rate_rad_s->z - ra_config.ki * limited_I.z;

        // Check exit conditions for FINE -> COARSE
        if (angle >= ra_config.fine_exit_rad || rate_mag >= ra_config.rate_exit_rad_s) {
            ra_state.mode = RA_COARSE;
            ra_state.transition_samples = 0;
            ra_state.integral_error_rad_s.x = 0.0;
            ra_state.integral_error_rad_s.y = 0.0;
            ra_state.integral_error_rad_s.z = 0.0;
        } else {
            // Check entry conditions for HOLD
            if (angle <= ra_config.hold_enter_rad && rate_mag <= ra_config.hold_rate_rad_s) {
                ra_state.transition_samples++;
                if (ra_state.transition_samples >= ra_config.hold_samples) {
                    ra_state.mode = RA_HOLD;
                    ra_state.transition_samples = 0;
                }
            } else {
