adcs_quat_t q_err = adcs_quat_multiply(&q_tgt_norm, &q_curr_conj);
if (q_err.w < 0.0) {
    q_err.w = -q_err.w; q_err.x = -q_err.x; q_err.y = -q_err.y; q_err.z = -q_err.z;
}

double angle_rad = 2.0 * acos(q_err.w);
adcs_vec3_t e = {0,0,0};
if (angle_rad > 1e-12) {
    double sin_half = sqrt(1.0 - q_err.w * q_err.w);
    if (sin_half > 1e-12) {
        double scale = angle_rad / sin_half;
        e.x = q_err.x * scale; e.y = q_err.y * scale; e.z = q_err.z * scale;
    }
}

