adcs_vec3_t w = *ra_input.body_rate_rad_s;

ra_mode_t current_mode = ra_state.mode;
uint32_t trans_cnt = ra_state.transition_samples;
ra_mode_t next_mode = current_mode;

switch (current_mode) {
    case RA_OFF:
        next_mode = (rate_mag > re) ? RA_RATE_DAMP : RA_COARSE;
        break;
    case RA_RATE_DAMP:
        if (rate_mag <= re) {
            trans_cnt++;
            if (trans_cnt >= rate_cnt_req) next_mode = RA_COARSE;
        } else if (rate_mag >= rx) {
            trans_cnt = 0;
        }
        break;
    case RA_COARSE:
        if (angle_rad <= fe && rate_mag <= re) {
            trans_cnt++;
            if (trans_cnt >= fine_cnt_req) next_mode = RA_FINE;
        } else {
            trans_cnt = 0;
        }
        break;
    case RA_FINE:
        if (angle_rad >= fx || rate_mag >= rx) {
            next_mode = RA_COARSE;
            ra_state.integral_error_rad_s = (adcs_vec3_t){0,0,0};
            trans_cnt = 0;
        } else {
            if (angle_rad <= he && rate_mag <= hr) {
                trans_cnt++;
                if (trans_cnt >= hold_cnt_req) next_mode = RA_HOLD;
            } else {
                trans_cnt = 0;
            }
        }
        break;
    case RA_HOLD:
        if (angle_rad >= hx || rate_mag >= hrx) {
            next_mode = RA_FINE;
            trans_cnt = 0;
        }
        break;
    case RA_FAULT:
        next_mode = RA_FAULT;
        break;
}

int is_rejected = 0;
reject_cycle_label:
if (is_rejected) {
    ra_state.transition_samples = 0;
    ra_state.integral_error_rad_s = (adcs_vec3_t){0,0,0};
    ra_state.bad_samples++;
    if (ra_state.bad_samples >= max_bad) next_mode = RA_FAULT;
    ra_output.torque_nm = (adcs_vec3_t){0,0,0};
    ra_output.saturation_mask = 0;
    ra_output.error_angle_rad = 0;
    ra_output.rate_magnitude_rad_s = 0;
    ra_state.mode = next_mode;
    ra_output.mode = next_mode;
    ra_output.bad_samples = ra_state.bad_samples;
    return;
}

ra_state.mode = next_mode;
ra_state.transition_samples = trans_cnt;

adcs_vec3_t torque_proposed = {0,0,0};
adcs_vec3_t torque_limited = {0,0,0};
uint32_t sat_mask = 0;
adcs_actuator_limit_t limit = {-tlim, tlim, 0};

switch (next_mode) {
    case RA_RATE_DAMP:
        torque_proposed = adcs_vec3_scale(&w, -kd);
        break;
    case RA_COARSE:
        torque_proposed.x = -kp*e.x - kd*w.x;
        torque_proposed.y = -kp*e.y - kd*w.y;
        torque_proposed.z = -kp*e.z - kd*w.z;
        break;
    case RA_FINE:
    case RA_HOLD: {
        adcs_vec3_t I_new;
        I_new.x = ra_state.integral_error_rad_s.x + e.x * dt;
        I_new.y = ra_state.integral_error_rad_s.y + e.y * dt;
        I_new.z = ra_state.integral_error_rad_s.z + e.z * dt;
        I_new.x = ADCS_CLAMP(I_new.x, -ilim, ilim);
        I_new.y = ADCS_CLAMP(I_new.y, -ilim, ilim);
        I_new.z = ADCS_CLAMP(I_new.z, -ilim, ilim);

        torque_proposed.x = -kp*e.x - kd*w.x - ki*I_new.x;
        torque_proposed.y = -kp*e.y - kd*w.y - ki*I_new.y;
        torque_proposed.z = -kp*e.z - kd*w.z - ki*I_new.z;

        double lv;
        adcs_limit_scalar(torque_proposed.x, &limit, &lv);
        if (fabs(lv) == tlim && ((torque_proposed.x > 0 && lv < torque_proposed.x) || (torque_proposed.x < 0 && lv > torque_proposed.x))) sat_mask |= 1;
        torque_limited.x = lv;

        adcs_limit_scalar(torque_proposed.y, &limit, &lv);
        if (fabs(lv) == tlim && ((torque_proposed.y > 0 && lv < torque_proposed.y) || (torque_proposed.y < 0 && lv > torque_proposed.y))) sat_mask |= 2;
        torque_limited.y = lv;

        adcs_limit_scalar(torque_proposed.z, &limit, &lv);
        if (fabs(lv) == tlim && ((torque_proposed.z > 0 && lv < torque_proposed.z) || (torque_proposed.z < 0 && lv > torque_proposed.z))) sat_mask |= 4;
        torque_limited.z = lv;

        adcs_vec3_t I_old = ra_state.integral_error_rad_s;
        adcs_vec3_t torque_pd = {-kp*e.x - kd*w.x, -kp*e.y - kd*w.y, -kp*e.z - kd*w.z};
        adcs_vec3_t I_used = I_new;

        if ((sat_mask & 1)) {
            double T_old = torque_pd.x - ki*I_old.x;
            if (fabs(T_old) < fabs(torque_proposed.x)) I_used.x = I_old.x;
        }
        if ((sat_mask & 2)) {
            double T_old = torque_pd.y - ki*I_old.y;
            if (fabs(T_old) < fabs(torque_proposed.y)) I_used.y = I_old.y;
        }
        if ((sat_mask & 4)) {
            double T_old = torque_pd.z - ki*I_old.z;
            if (fabs(T_old) < fabs(torque_proposed.z)) I_used.z = I_old.z;
        }

        adcs_vec3_t torque_recalc = {-kp*e.x - kd*w.x - ki*I_used.x, -kp*e.y - kd*w.y - ki*I_used.y, -kp*e.z - kd*w.z - ki*I_used.z};
        adcs_limit_scalar(torque_recalc.x, &limit, &lv); torque_limited.x = lv;
        adcs_limit_scalar(torque_recalc.y, &limit, &lv); torque_limited.y = lv;
        adcs_limit_scalar(torque_recalc.z, &limit, &lv); torque_limited.z = lv;

        ra_state.integral_error_rad_s.x = ((sat_mask & 1) && I_used.x == I_old.x) ? I_old.x : I_new.x;
        ra_state.integral_error_rad_s.y = ((sat_mask & 2) && I_used.y == I_old.y) ? I_old.y : I_new.y;
        ra_state.integral_error_rad_s.z = ((sat_mask & 4) && I_used.z == I_old.z) ? I_old.z : I_new.z;
        break;
    }
    default:
        torque_limited = (adcs_vec3_t){0,0,0};
        break;
}

ra_state.bad_samples = 0;
ra_output.torque_nm = torque_limited;
ra_output.saturation_mask = sat_mask;
ra_output.error_angle_rad = angle_rad;
ra_output.rate_magnitude_rad_s = rate_mag;
ra_output.mode = next_mode;
ra_output.bad_samples = 0;

